def configure_utf8_console():
    """Ưu tiên UTF-8 khi PowerShell đang trả về bảng mã cp1252."""
    for stream in (sys.stdout, sys.stderr):
        if hasattr(stream, 'reconfigure'):
            try:
                stream.reconfigure(encoding='utf-8', errors='replace')
            except (OSError, ValueError):
                pass


def configure_tesseract():
    """Tìm Tesseract tại vị trí Windows thông dụng mà không sửa PATH hệ thống."""
    import pytesseract
    if shutil.which('tesseract'):
        return
    if os.name != 'nt':
        return
    candidates = [
        Path(os.environ.get('ProgramFiles', r'C:\Program Files')) / 'Tesseract-OCR' / 'tesseract.exe',
        Path(os.environ.get('ProgramFiles(x86)', r'C:\Program Files (x86)')) / 'Tesseract-OCR' / 'tesseract.exe',
        Path(os.environ.get('LOCALAPPDATA', '')) / 'Programs' / 'Tesseract-OCR' / 'tesseract.exe',
    ]
    for candidate in candidates:
        if candidate.is_file():
            pytesseract.pytesseract.tesseract_cmd = str(candidate)
            return


def project(p):
    return ROOT / p


def dump_csv(p, rows, headers):
    p = project(p) if isinstance(p, str) else p
    p.parent.mkdir(parents=True, exist_ok=True)
    with open(p, 'w', newline='', encoding='utf-8-sig') as f:
        w = csv.DictWriter(f, fieldnames=headers, extrasaction='ignore')
        w.writeheader()
        w.writerows(rows)


def replace_csvs_atomically(specs):
    """Ghi nhiều CSV qua file tạm; khôi phục bản cũ nếu một lần thay thế bị lỗi."""
    token = f'{os.getpid()}_{datetime.now(timezone.utc).strftime("%Y%m%d%H%M%S%f")}'
    staged = []
    backups = []
    replaced = []
    try:
        for path, rows, headers in specs:
            path.parent.mkdir(parents=True, exist_ok=True)
            temp = path.with_name(f'.{path.name}.{token}.tmp')
            dump_csv(temp, rows, headers)
            staged.append((path, temp))
        for path, _ in staged:
            backup = path.with_name(f'.{path.name}.{token}.bak')
            if path.exists():
                shutil.copy2(path, backup)
                backups.append((path, backup, True))
            else:
                backups.append((path, backup, False))
        for path, temp in staged:
            os.replace(temp, path)
            replaced.append(path)
    except Exception:
        for path, backup, existed in reversed(backups):
            if backup.exists():
                os.replace(backup, path)
            elif not existed and path in replaced and path.exists():
                path.unlink()
        raise
    finally:
        for _, temp in staged:
            if temp.exists():
                temp.unlink()
        for _, backup, _ in backups:
            if backup.exists():
                backup.unlink()


def read_csv(p):
    p = project(p) if isinstance(p, str) else p
    if not p.exists():
        raise SystemExit(f'CHƯA CÓ FILE: {p}')
    return pd.read_csv(p, dtype=str, keep_default_na=False)


def require_columns(df, columns, name):
    missing = [c for c in columns if c not in df.columns]
    if missing:
        raise SystemExit(f'{name}: thiếu cột {", ".join(missing)}')


def no_overwrite(p, force=False):
    if p.exists() and not force:
        raise SystemExit(f'TỆP ĐÃ TỒN TẠI: {p}; muốn ghi đè phải dùng --force sau khi sao lưu.')


def sha256(path):
    h = hashlib.sha256()
    with path.open('rb') as f:
        while block := f.read(1024 * 1024):
            h.update(block)
    return h.hexdigest()


def slug(s):
    s = unicodedata.normalize('NFKD', s)
    s = ''.join(c for c in s if not unicodedata.combining(c))
    s = re.sub(r'[^\w-]+', '_', s, flags=re.UNICODE)
    return s[:65].strip('_') or 'document'


def stripped(s):
    return re.sub(r'\s+', ' ', str(s).strip())


def normalized(s):
    s = unicodedata.normalize('NFKD', str(s).lower())
    s = ''.join(c for c in s if not unicodedata.combining(c))
    return s.replace('đ', 'd')


def normalized_relative_path(value):
    """Chuẩn hóa đường dẫn tương đối để so sánh an toàn trên Windows."""
    return str(value).replace('/', '\\').casefold()


def unique_document_id(path, file_hash, used_ids):
    """Sinh mã mới mà không bao giờ thay đổi mã đã tồn tại."""
    stem = slug(path.stem)
    for width in (8, 12, 16, 24, 64):
        candidate = f'{stem}_{file_hash[:width]}'
        if candidate not in used_ids:
            return candidate
    suffix = 2
    while f'{stem}_{file_hash}_{suffix}' in used_ids:
        suffix += 1
    return f'{stem}_{file_hash}_{suffix}'


def write_incremental_log(payload):
    evidence = project('evidence')
    evidence.mkdir(parents=True, exist_ok=True)
    stamp = datetime.now(timezone.utc).strftime('%Y%m%d_%H%M%S_%f')
    path = evidence / f'ingest_incremental_{stamp}.json'
    temp = evidence / f'.{path.name}.tmp'
    temp.write_text(json.dumps(payload, ensure_ascii=False, indent=2), encoding='utf-8')
    os.replace(temp, path)
    return path


def init(args):
    for folder in ['data/raw', 'data/processed', 'data/annotations', 'data/splits', 'config', 'results/predictions', 'results/metrics', 'results/errors', 'evidence', 'paper']:
        project(folder).mkdir(parents=True, exist_ok=True)
    for p, head in [
        ('data/processed/documents_manifest.csv', MANIFEST),
        ('data/processed/candidate_segments.csv', DRAFT),
        ('data/annotations/segments_gold.csv', SEGMENTS),
        ('data/annotations/tasks_gold.csv', TASKS),
        ('data/annotations/extraction_predictions.csv', TASK_PRED),
        ('data/annotations/e5_matches.csv', E5),
    ]:
        if not project(p).exists():
            dump_csv(p, [], head)
    print('Đã tạo cây thư mục, CSV khung (không có dữ liệu thực nghiệm).')


def ocr_page(page):
    import pytesseract
    from PIL import Image
    from io import BytesIO
    configure_tesseract()
    pix = page.get_pixmap(matrix=__import__('fitz').Matrix(2, 2), alpha=False)
    im = Image.open(BytesIO(pix.tobytes('png')))
    return pytesseract.image_to_string(im, lang='vie+eng', config='--psm 3')


def segments_of_file(path, do_ocr=False):
    ext = path.suffix.lower()
    if ext in {'.txt'}:
        return [(f'line:{i}', stripped(x)) for i, x in enumerate(path.read_text(encoding='utf-8-sig').splitlines(), 1) if stripped(x)]
    if ext == '.docx':
        from docx import Document
        d = Document(str(path))
        out = []
        # These remain in actual document order on current python-docx.
        if hasattr(d, 'iter_inner_content'):
            for i, item in enumerate(d.iter_inner_content(), 1):
                if hasattr(item, 'rows'):
                    for r, row in enumerate(item.rows, 1):
                        s = ' | '.join(stripped(c.text) for c in row.cells)
                        if s.strip(' |'): out.append((f'block:{i}/row:{r}', s))
                else:
                    s = stripped(item.text)
                    if s: out.append((f'block:{i}', s))
        else:
            for i, para in enumerate(d.paragraphs, 1):
                s = stripped(para.text)
                if s: out.append((f'paragraph:{i}', s))
        return out
    if ext == '.pdf':
        import fitz
        doc = fitz.open(str(path))
        out = []
        for ip, page in enumerate(doc, 1):
            blocks = [(b[1], b[0], stripped(b[4])) for b in page.get_text('blocks') if len(b) >= 5 and isinstance(b[4], str) and stripped(b[4])]
            blocks.sort(key=lambda x: (round(x[0] / 8), x[1]))
            if len(' '.join(b[2] for b in blocks)) < 30 and do_ocr:
                s = stripped(ocr_page(page))
                if s: out.append((f'page:{ip}/OCR', s))
            elif len(' '.join(b[2] for b in blocks)) < 30:
                print(f'CẦN OCR/kiểm tra: {path.name}, trang {ip}', file=sys.stderr)
            else:
                for ib, b in enumerate(blocks, 1):
                    out.append((f'page:{ip}/block:{ib}', b[2]))
        return out
    if ext in {'.png', '.jpg', '.jpeg', '.tif', '.tiff'}:
        if not do_ocr:
            print(f'CẦN OCR: {path.name}', file=sys.stderr)
            return []
        import pytesseract
        from PIL import Image
        configure_tesseract()
        return [('image:1/OCR', stripped(pytesseract.image_to_string(Image.open(path), lang='vie+eng')))]
    return []


def ingest_incremental(args, docs, manfile, segfile):
    """Chỉ nối thêm tài liệu mới; không sửa hàng cũ hoặc nhãn đã có."""
    if getattr(args, 'force', False):
        raise SystemExit('Không kết hợp --incremental với --force. Incremental không ghi đè dữ liệu cũ.')

    manifest = read_csv(manfile)
    segments = read_csv(segfile)
    require_columns(manifest, MANIFEST, 'documents_manifest.csv')
    require_columns(segments, DRAFT, 'candidate_segments.csv')
    if manifest.document_id.duplicated().any():
        raise SystemExit('Manifest có document_id trùng; phải xử lý trước khi ingest incremental.')
    if segments.segment_id.duplicated().any():
        raise SystemExit('candidate_segments có segment_id trùng; phải xử lý trước khi ingest incremental.')
    if not segments.empty and not segments.document_id.isin(manifest.document_id).all():
        raise SystemExit('candidate_segments có document_id không tồn tại trong manifest; dừng để tránh làm hỏng dữ liệu.')

    manifest_rows = manifest.to_dict('records')
    segment_rows = segments.to_dict('records')
    manifest_headers = list(manifest.columns)
    segment_headers = list(segments.columns)
    used_ids = set(manifest.document_id)
    used_segment_ids = set(segments.segment_id)
    known_hashes = defaultdict(list)
    known_paths = {}
    for record in manifest_rows:
        known_hashes[record['file_sha256'].lower()].append(record)
        known_paths[normalized_relative_path(record['filename'])] = record

    raw_relative_paths = {
        normalized_relative_path(str(path.relative_to(ROOT))): path for path in docs
    }
    missing_manifest_files = [
        record['filename'] for record in manifest_rows
        if normalized_relative_path(record['filename']) not in raw_relative_paths
    ]
    log = dict(
        utc=datetime.now(timezone.utc).isoformat(),
        mode='incremental',
        ocr=bool(args.ocr),
        manifest_rows_before=len(manifest_rows),
        segment_rows_before=len(segment_rows),
        scanned_files=len(docs),
        new_documents=[],
        skipped_duplicates=[],
        modified_documents=[],
        missing_manifest_files=missing_manifest_files,
        errors=[],
        annotations_appended=0,
    )

    new_manifest_rows = []
    new_segment_rows = []
    for path in docs:
        relative = str(path.relative_to(ROOT))
        relative_key = normalized_relative_path(relative)
        try:
            file_hash = sha256(path).lower()
        except Exception as exc:
            log['errors'].append(dict(filename=relative, stage='sha256', error=str(exc)))
            print(f'LỖI đọc/hash {relative}: {exc}', file=sys.stderr)
            continue

        if relative_key in known_paths:
            old = known_paths[relative_key]
            if file_hash == old['file_sha256'].lower():
                log['skipped_duplicates'].append(dict(
                    filename=relative,
                    file_sha256=file_hash,
                    reason='same_path_and_hash',
                    existing_filenames=[old['filename']],
                ))
                continue
            warning = dict(
                filename=relative,
                document_id=old['document_id'],
                recorded_sha256=old['file_sha256'],
                current_sha256=file_hash,
                action='skipped_requires_separate_review',
            )
            log['modified_documents'].append(warning)
            print(
                f'CẢNH BÁO: file cũ đã đổi nội dung: {relative}; '
                'không nhập và không ghi đè. Hãy xử lý phiên bản riêng.',
                file=sys.stderr,
            )
            continue

        if file_hash in known_hashes:
            originals = [record['filename'] for record in known_hashes[file_hash]]
            log['skipped_duplicates'].append(dict(
                filename=relative,
                file_sha256=file_hash,
                reason='same_hash_different_name',
                existing_filenames=originals,
            ))
            print(f'BỎ QUA bản đổi tên/trùng nội dung: {relative} (SHA256 đã có).')
            continue

        try:
            items = segments_of_file(path, args.ocr)
            if not items:
                raise ValueError('Không trích xuất được đoạn; nếu là ảnh/scan hãy chạy lại với --ocr.')
            document_id = unique_document_id(path, file_hash, used_ids)
            candidate_rows = []
            for index, (location, text_value) in enumerate(items, 1):
                segment_id = f'{document_id}_S{index:04d}'
                if segment_id in used_segment_ids:
                    raise ValueError(f'Segment ID xung đột: {segment_id}')
                candidate_rows.append(dict(
                    document_id=document_id,
                    segment_id=segment_id,
                    source_location=location,
                    segment_text=text_value,
                ))
            manifest_record = dict(
                document_id=document_id,
                filename=relative,
                file_sha256=file_hash,
                family_id='',
                doc_date='',
                doc_type=path.suffix.lower().lstrip('.'),
                source_url_or_archive='',
                permission_basis='',
                access_level='',
                anonymized='',
                notes='CẦN ĐIỀN METADATA; THÊM BẰNG INGEST INCREMENTAL',
            )
            new_manifest_rows.append(manifest_record)
            new_segment_rows.extend(candidate_rows)
            used_ids.add(document_id)
            used_segment_ids.update(row['segment_id'] for row in candidate_rows)
            known_hashes[file_hash].append(manifest_record)
            known_paths[relative_key] = manifest_record
            log['new_documents'].append(dict(
                filename=relative,
                document_id=document_id,
                file_sha256=file_hash,
                segment_count=len(candidate_rows),
            ))
            print(f'Đọc mới {path.name}: {len(candidate_rows)} đoạn')
        except Exception as exc:
            log['errors'].append(dict(filename=relative, stage='extract', error=str(exc)))
            print(f'LỖI xử lý {relative}: {exc}', file=sys.stderr)

    annotation_spec = None
    annotations_path = project('data/annotations/segments_gold.csv')
    if new_segment_rows and annotations_path.exists():
        annotations = read_csv(annotations_path)
        require_columns(annotations, SEGMENTS, 'segments_gold.csv')
        if annotations.segment_id.duplicated().any():
            raise SystemExit('segments_gold.csv có segment_id trùng; không thể bổ sung an toàn.')
        if not annotations.empty:
            annotation_ids = set(annotations.segment_id)
            additions = []
            for row in new_segment_rows:
                if row['segment_id'] in annotation_ids:
                    continue
                additions.append(dict(
                    document_id=row['document_id'],
                    segment_id=row['segment_id'],
                    source_location=row['source_location'],
                    segment_text=row['segment_text'],
                    task_present='',
                    commune_relevance='',
                    annotator_id='',
                    label_status='',
                    notes='',
                ))
            if additions:
                annotation_rows = annotations.to_dict('records') + additions
                annotation_spec = (annotations_path, annotation_rows, list(annotations.columns))
                log['annotations_appended'] = len(additions)

    if new_manifest_rows:
        specs = [
            (manfile, manifest_rows + new_manifest_rows, manifest_headers),
            (segfile, segment_rows + new_segment_rows, segment_headers),
        ]
        if annotation_spec:
            specs.append(annotation_spec)
        try:
            replace_csvs_atomically(specs)
        except Exception as exc:
            log['errors'].append(dict(filename='', stage='commit', error=str(exc)))
            log['committed'] = False
            log_path = write_incremental_log(log)
            raise SystemExit(f'Không thể ghi cập nhật; dữ liệu cũ đã được khôi phục. Log: {log_path}; lỗi: {exc}')
        log['committed'] = True
    else:
        log['committed'] = False

    log['new_document_count'] = len(new_manifest_rows)
    log['skipped_duplicate_count'] = len(log['skipped_duplicates'])
    log['modified_document_count'] = len(log['modified_documents'])
    log['error_count'] = len(log['errors'])
    log['segments_appended'] = len(new_segment_rows)
    log['manifest_rows_after'] = len(manifest_rows) + len(new_manifest_rows)
    log['segment_rows_after'] = len(segment_rows) + len(new_segment_rows)
    log_path = write_incremental_log(log)
    skipped_total = log['skipped_duplicate_count'] + log['modified_document_count']
    print(
        f'Incremental: mới={log["new_document_count"]}, bỏ qua={skipped_total} '
        f'(trùng={log["skipped_duplicate_count"]}, đã sửa={log["modified_document_count"]}), '
        f'đoạn bổ sung={log["segments_appended"]}, lỗi={log["error_count"]}, '
        f'nhãn trống bổ sung={log["annotations_appended"]}.'
    )
    print(f'Nhật ký: {log_path}')


def ingest(args):
    raw = project('data/raw')
    docs = [p for p in sorted(raw.rglob('*')) if p.is_file() and p.suffix.lower() in {'.docx', '.pdf', '.txt', '.png', '.jpg', '.jpeg', '.tif', '.tiff'}]
    if not docs:
        raise SystemExit('CHƯA CÓ FILE. Sao chép văn bản được phép nghiên cứu vào data/raw/')
    manfile = project('data/processed/documents_manifest.csv')
    segfile = project('data/processed/candidate_segments.csv')
    if getattr(args, 'incremental', False):
        return ingest_incremental(args, docs, manfile, segfile)
    if not args.force and ((manfile.exists() and len(read_csv(manfile)) > 0) or (segfile.exists() and len(read_csv(segfile)) > 0)):
        raise SystemExit('Đã có manifest/candidate_segments. Sao lưu và dùng --force nếu thực sự muốn ghi đè.')
    mans, segs = [], []
    for path in docs:
        h = sha256(path)
        doc_id = f'{slug(path.stem)}_{h[:8]}'
        mans.append(dict(document_id=doc_id, filename=str(path.relative_to(ROOT)), file_sha256=h, family_id='', doc_date='', doc_type=path.suffix.lower().lstrip('.'), source_url_or_archive='', permission_basis='', access_level='', anonymized='', notes='CẦN ĐIỀN METADATA'))
        items = segments_of_file(path, args.ocr)
        for i, (loc, s) in enumerate(items, 1):
            segs.append(dict(document_id=doc_id, segment_id=f'{doc_id}_S{i:04d}', source_location=loc, segment_text=s))
        print(f'Đọc {path.name}: {len(items)} đoạn')
    dump_csv(manfile, mans, MANIFEST)
    dump_csv(segfile, segs, DRAFT)
    print(f'Tổng: {len(mans)} văn bản, {len(segs)} đoạn. Điền manifest; tạo nhãn bằng prepare-annotations.')


def prepare_annotations(args):
    inp = read_csv('data/processed/candidate_segments.csv')
    out = project('data/annotations/segments_gold.csv')
    if out.exists() and len(read_csv(out)) > 0 and not args.force:
        raise SystemExit('segments_gold.csv đã có dữ liệu, không ghi đè nhãn; hãy sao lưu nếu dùng --force.')
    rows = []
    for r in inp.to_dict('records'):
        r.update(task_present='', commune_relevance='', annotator_id='', label_status='', notes='')
        rows.append(r)
    dump_csv(out, rows, SEGMENTS)
    print(f'Đã sinh {len(rows)} hàng để gán nhãn; chưa có nhãn thực tế.')


def validate(args):
    m = read_csv('data/processed/documents_manifest.csv')
    s = read_csv('data/annotations/segments_gold.csv')
    t = read_csv('data/annotations/tasks_gold.csv')
    issues = []
    for name, df, col in [('manifest', m, 'document_id'), ('segments', s, 'segment_id'), ('tasks', t, 'task_id')]:
        if col not in df: issues.append(f'{name}: thiếu {col}'); continue
        if df[col].duplicated().any(): issues.append(f'{name}: {int(df[col].duplicated().sum())} mã trùng')
        if df[col].eq('').any(): issues.append(f'{name}: có {int(df[col].eq("").sum())} mã trống')
    if m.empty: issues.append('manifest: chưa có văn bản')
    for c in ['family_id', 'source_url_or_archive', 'permission_basis', 'access_level']:
        if c not in m: issues.append(f'manifest: thiếu cột {c}')
        elif m[c].eq('').any(): issues.append(f'manifest: {int(m[c].eq("").sum())} hàng thiếu {c}')
    accepted = s[s['label_status'].str.lower().eq('approved')] if 'label_status' in s else s.iloc[:0]
    for c in ['task_present', 'commune_relevance']:
        if c not in accepted: issues.append(f'segments: thiếu cột {c}')
        elif (~accepted[c].isin(['0','1'])).any(): issues.append(f'segments approved: nhãn {c} không thuộc 0/1')
    for c in ['task_id', 'document_id', 'task_text', 'source_text', 'source_location', 'evidence_source']:
        if c not in t: issues.append(f'tasks: thiếu cột {c}')
    if not t.empty:
        if t.document_id.isin(m.document_id).eq(False).any(): issues.append('tasks: document_id không có trong manifest')
        approved = t[t.label_status.str.lower().eq('approved')]
        for c in ['task_text','source_text','evidence_source','annotator_id']:
            if approved[c].eq('').any(): issues.append(f'tasks approved: thiếu {c}')
        eligible = approved[approved.commune_relevance.eq('1')]
        if eligible.gold_unit.eq('').any(): issues.append('tasks approved liên quan cấp xã: có gold_unit trống; xem xét nhãn cần xác nhận')
    if not s.empty and not s.document_id.isin(m.document_id).all(): issues.append('segments: có document_id không nằm trong manifest')
    if not accepted.empty and accepted.annotator_id.eq('').any(): issues.append('segments approved: thiếu annotator_id')
    print(f'{len(m)} văn bản, {len(s)} đoạn, {len(accepted)} đoạn approved, {len(t)} nhiệm vụ')
    if issues:
        for issue in issues: print('CẦN XỬ LÝ:', issue)
        sys.exit(1)
    print('Đạt các kiểm tra kỹ thuật cơ bản (không thay thế kiểm tra chất lượng gán nhãn).')


def quality_report(args):
    """Xuất thống kê QC dẫn xuất; không sửa manifest, đoạn ứng viên hoặc tài liệu gốc."""
    manifest = read_csv('data/processed/documents_manifest.csv')
    segments = read_csv('data/processed/candidate_segments.csv')
    require_columns(manifest, MANIFEST, 'documents_manifest.csv')
    require_columns(segments, DRAFT, 'candidate_segments.csv')

    out_dir = project(args.output_dir)
    summary_path = out_dir / 'dataset_quality_summary.csv'
    document_path = out_dir / 'document_quality.csv'
    page_path = out_dir / 'page_quality.csv'
    for path in (summary_path, document_path, page_path):
        no_overwrite(path, args.force)

    duplicate_mask = segments.duplicated('segment_text', keep=False)
    duplicate_groups = segments.loc[duplicate_mask, 'segment_text'].nunique()
    document_ids = set(manifest.document_id)
    segment_document_ids = set(segments.document_id)
    summary = []

    def metric(name, value, note=''):
        summary.append(dict(metric=name, value=value, note=note))

    metric('manifest_documents', len(manifest))
    metric('candidate_segments', len(segments))
    metric('unique_document_id_manifest', manifest.document_id.nunique())
    metric('unique_document_id_segments', segments.document_id.nunique())
    metric('unique_segment_id', segments.segment_id.nunique())
    metric('duplicate_segment_id_rows', int(segments.segment_id.duplicated(keep=False).sum()))
    metric('blank_segment_text', int(segments.segment_text.str.strip().eq('').sum()))
    metric('segments_text_length_lt_20', int(segments.segment_text.str.len().lt(20).sum()))
    metric('segments_text_length_lt_30', int(segments.segment_text.str.len().lt(30).sum()))
    metric('segments_text_length_ge_1000', int(segments.segment_text.str.len().ge(1000).sum()))
    metric('duplicate_text_groups', int(duplicate_groups), 'Trùng chính xác; không tự động coi là lỗi.')
    metric('rows_in_duplicate_text_groups', int(duplicate_mask.sum()))
    metric('ocr_source_rows', int(segments.source_location.str.endswith('/OCR').sum()))
    metric('manifest_without_segments', len(document_ids - segment_document_ids))
    metric('segments_document_not_in_manifest', len(segment_document_ids - document_ids))
    for column in ['family_id', 'doc_date', 'source_url_or_archive', 'permission_basis', 'access_level', 'anonymized']:
        metric(f'manifest_blank_{column}', int(manifest[column].str.strip().eq('').sum()))

    document_rows = []
    page_rows = []
    raw_status_counts = defaultdict(int)
    root_resolved = ROOT.resolve()
    for record in manifest.to_dict('records'):
        doc_id = record['document_id']
        doc_segments = segments[segments.document_id.eq(doc_id)]
        page_numbers = []
        for location in doc_segments.source_location:
            match = re.match(r'^page:(\d+)(?:/|$)', location)
            if match:
                page_numbers.append(int(match.group(1)))
        page_counts = pd.Series(page_numbers, dtype='int64').value_counts().to_dict()

        raw_status = 'missing'
        raw_pages = ''
        pages_without_segments = []
        low_native_text_pages = []
        raw_path = (ROOT / record['filename']).resolve()
        try:
            raw_path.relative_to(root_resolved)
            inside_root = True
        except ValueError:
            inside_root = False
        if not inside_root:
            raw_status = 'outside_project_root'
        elif raw_path.is_file():
            current_hash = sha256(raw_path)
            raw_status = 'ok' if current_hash.lower() == record['file_sha256'].lower() else 'hash_mismatch'
            if raw_path.suffix.lower() == '.pdf':
                import pymupdf
                with pymupdf.open(raw_path) as pdf:
                    raw_pages = pdf.page_count
                    for page_number, page in enumerate(pdf, 1):
                        native_chars = len(stripped(page.get_text()))
                        extracted_count = int(page_counts.get(page_number, 0))
                        if extracted_count == 0:
                            pages_without_segments.append(page_number)
                        if native_chars < 30:
                            low_native_text_pages.append(page_number)
                        if extracted_count == 0 and native_chars < 30:
                            status = 'no_segments_low_native_text'
                        elif extracted_count == 0:
                            status = 'no_segments_has_native_text'
                        elif native_chars < 30:
                            status = 'segments_low_native_text'
                        else:
                            status = 'ok'
                        page_rows.append(dict(
                            document_id=doc_id,
                            page_number=page_number,
                            native_text_chars=native_chars,
                            extracted_segment_count=extracted_count,
                            status=status,
                        ))
        raw_status_counts[raw_status] += 1
        document_rows.append(dict(
            document_id=doc_id,
            filename=record['filename'],
            raw_status=raw_status,
            raw_page_count=raw_pages,
            extracted_segments=len(doc_segments),
            unique_segment_id=doc_segments.segment_id.nunique(),
            pages_with_segments=len(set(page_numbers)),
            pages_without_segments=';'.join(map(str, pages_without_segments)),
            low_native_text_pages=';'.join(map(str, low_native_text_pages)),
            short_segments_lt_20=int(doc_segments.segment_text.str.len().lt(20).sum()),
            duplicate_text_rows=int(doc_segments.duplicated('segment_text', keep=False).sum()),
        ))

    for status, count in sorted(raw_status_counts.items()):
        metric(f'raw_status_{status}', count)

    dump_csv(summary_path, summary, ['metric', 'value', 'note'])
    dump_csv(document_path, document_rows, list(document_rows[0].keys()) if document_rows else [
        'document_id', 'filename', 'raw_status', 'raw_page_count', 'extracted_segments',
        'unique_segment_id', 'pages_with_segments', 'pages_without_segments',
        'low_native_text_pages', 'short_segments_lt_20', 'duplicate_text_rows',
    ])
    dump_csv(page_path, page_rows, list(page_rows[0].keys()) if page_rows else [
        'document_id', 'page_number', 'native_text_chars', 'extracted_segment_count', 'status',
    ])
    print(f'Đã xuất QC không phá hủy: {summary_path}, {document_path}, {page_path}')
    print('Không có nội dung toàn văn nào được ghi vào báo cáo QC.')


def split(args):
    m = read_csv('data/processed/documents_manifest.csv')
    if len(m) < 12 or m.family_id.eq('').any():
        raise SystemExit('Cần ít nhất 12 văn bản, mọi hàng phải có family_id, và số nhóm đủ để chia 3 tập.')
    if m.family_id.nunique() < 12:
        raise SystemExit('Cần ít nhất 12 nhóm family_id phân biệt. Tài liệu gần trùng phải cùng một nhóm.')
    ids = m.document_id.to_numpy()
    groups = m.family_id.to_numpy()
    gss1 = GroupShuffleSplit(n_splits=1, test_size=args.test_size, random_state=args.seed)
    trdev, test = next(gss1.split(ids, groups=groups))
    gss2 = GroupShuffleSplit(n_splits=1, test_size=args.dev_size/(1-args.test_size), random_state=args.seed)
    tr_sub, dev_sub = next(gss2.split(ids[trdev], groups=groups[trdev]))
    splitmap = {}
    for x in trdev[tr_sub]: splitmap[str(ids[x])] = 'train'
    for x in trdev[dev_sub]: splitmap[str(ids[x])] = 'dev'
    for x in test: splitmap[str(ids[x])] = 'test'
    out = project('data/splits/split_manifest.csv')
    no_overwrite(out, args.force)
    m['split'] = m.document_id.map(splitmap)
    assert len(m) == len(splitmap)
    for a, b in [('train','dev'),('train','test'),('dev','test')]:
        assert set(m[m.split == a].family_id).isdisjoint(set(m[m.split == b].family_id))
    dump_csv(out, m.to_dict('records'), MANIFEST + ['split'])
    print(m.split.value_counts().to_string())
    print('Đã khóa split theo family_id. Không đổi seed/chia lại sau khi chọn mô hình trên dev/test.')

TASK_RX = re.compile(r'\b(giao|yeu cau|de nghi|chu tri|phoi hop|to chuc thuc hien|tham muu|trien khai|bao cao|hoan thanh|ra soat|thuc hien|xay dung ke hoach|tong hop)\b')
COMMUNE_RX = re.compile(r'\b(ubnd cac xa|ubnd cap xa|ubnd xa|ubnd phuong|xa phuong|cap xa|xa va phuong|cac xa|cac phuong)\b')


def sampling_features(segments):
    """Tạo đặc trưng chọn mẫu; các đặc trưng này không phải nhãn gold."""
    require_columns(segments, DRAFT, 'candidate_segments.csv')
    featured = segments.copy().reset_index(drop=True)
    lengths = featured.segment_text.str.len()
    featured['_length_bucket'] = pd.cut(
        lengths,
        bins=[-1, 19, 299, float('inf')],
        labels=['short_lt20', 'medium_20_299', 'long_ge300'],
    ).astype(str)
    featured['_heuristic_task'] = featured.segment_text.map(
        lambda text: int(bool(TASK_RX.search(normalized(text))))
    )
    featured['_duplicate_text'] = featured.duplicated('segment_text', keep=False).astype(int)
    featured['_table_like'] = featured.segment_text.str.contains('|', regex=False).astype(int)
    featured['_stratum'] = (
        'task' + featured['_heuristic_task'].astype(str)
        + '__' + featured['_length_bucket']
        + '__dup' + featured['_duplicate_text'].astype(str)
        + '__table' + featured['_table_like'].astype(str)
    )
    return featured


def select_pilot_rows(segments, n=80, seed=42, min_per_document=3):
    """Chọn mẫu đa dạng, xác định được bằng seed và không tạo nhãn nghiên cứu."""
    if n <= 0:
        raise SystemExit('--n phải lớn hơn 0')
    if min_per_document < 0:
        raise SystemExit('--min-per-document không được âm')
    if n > len(segments):
        raise SystemExit(f'Yêu cầu {n} đoạn nhưng chỉ có {len(segments)} đoạn ứng viên.')
    featured = sampling_features(segments)
    document_sizes = featured.groupby('document_id').size()
    if (document_sizes < min_per_document).any():
        bad = int((document_sizes < min_per_document).sum())
        raise SystemExit(f'Có {bad} văn bản không đủ {min_per_document} đoạn để bảo đảm mức tối thiểu.')
    minimum_required = len(document_sizes) * min_per_document
    if n < minimum_required:
        raise SystemExit(f'Cần n >= {minimum_required} để chọn ít nhất {min_per_document} đoạn cho mỗi văn bản.')

    rng = random.Random(seed)
    selected = []
    remaining = set(featured.index.tolist())

    def diverse_pick(indices, count):
        by_stratum = defaultdict(list)
        for index in indices:
            by_stratum[featured.at[index, '_stratum']].append(index)
        strata = sorted(by_stratum)
        rng.shuffle(strata)
        for values in by_stratum.values():
            rng.shuffle(values)
        chosen = []
        while len(chosen) < count and strata:
            next_strata = []
            for stratum in strata:
                if by_stratum[stratum] and len(chosen) < count:
                    chosen.append(by_stratum[stratum].pop())
                if by_stratum[stratum]:
                    next_strata.append(stratum)
            strata = next_strata
        return chosen

    # Mức nền bảo đảm mọi tài liệu đều có mặt, nhưng vẫn đa dạng độ dài/tín hiệu.
    for document_id in sorted(document_sizes.index):
        indices = featured.index[featured.document_id.eq(document_id)].tolist()
        chosen = diverse_pick(indices, min_per_document)
        selected.extend(chosen)
        remaining.difference_update(chosen)

    # Phần còn lại ưu tiên cân bằng tín hiệu có/không có từ khóa nhiệm vụ và các tầng ít gặp.
    desired_positive = n // 2
    while len(selected) < n:
        selected_positive = sum(int(featured.at[i, '_heuristic_task']) for i in selected)
        need_positive = selected_positive < desired_positive
        preferred = [i for i in remaining if bool(featured.at[i, '_heuristic_task']) == need_positive]
        pool = preferred or list(remaining)
        stratum_counts = defaultdict(int)
        for index in selected:
            stratum_counts[featured.at[index, '_stratum']] += 1
        minimum_count = min(stratum_counts[featured.at[i, '_stratum']] for i in pool)
        least_seen = [i for i in pool if stratum_counts[featured.at[i, '_stratum']] == minimum_count]
        chosen = rng.choice(sorted(least_seen))
        selected.append(chosen)
        remaining.remove(chosen)

    order_rng = random.Random(seed + 1)
    order_rng.shuffle(selected)
    pilot = featured.loc[selected].copy().reset_index(drop=True)
    pilot['pilot_order'] = range(1, len(pilot) + 1)
    return pilot


def sample_pilot(args):
    segments = read_csv('data/processed/candidate_segments.csv')
    pilot = select_pilot_rows(segments, args.n, args.seed, args.min_per_document)
    master_path = project(args.master)
    annotator_a_path = project(args.annotator_a)
    annotator_b_path = project(args.annotator_b)
    summary_path = project(args.summary)
    for path in (master_path, annotator_a_path, annotator_b_path, summary_path):
        no_overwrite(path, args.force)

    master_rows = []
    annotation_rows = []
    for record in pilot.to_dict('records'):
        master_rows.append(dict(
            document_id=record['document_id'],
            segment_id=record['segment_id'],
            source_location=record['source_location'],
            segment_text=record['segment_text'],
            pilot_order=record['pilot_order'],
            selection_stratum=record['_stratum'],
            heuristic_task_signal=record['_heuristic_task'],
            length_bucket=record['_length_bucket'],
            is_duplicate_text=record['_duplicate_text'],
            is_table_like=record['_table_like'],
        ))
        annotation_rows.append(dict(
            document_id=record['document_id'],
            segment_id=record['segment_id'],
            source_location=record['source_location'],
            segment_text=record['segment_text'],
            task_present='',
            commune_relevance='',
            annotator_id='',
            label_status='',
            notes='',
        ))

    summary_rows = [
        dict(group='overall', value='rows', count=len(pilot)),
        dict(group='overall', value='documents', count=pilot.document_id.nunique()),
    ]
    for column, group_name in [
        ('document_id', 'document_id'),
        ('_heuristic_task', 'heuristic_task_signal'),
        ('_length_bucket', 'length_bucket'),
        ('_duplicate_text', 'is_duplicate_text'),
        ('_table_like', 'is_table_like'),
    ]:
        for value, count in pilot[column].value_counts(dropna=False).sort_index().items():
            summary_rows.append(dict(group=group_name, value=value, count=int(count)))

    dump_csv(master_path, master_rows, PILOT_AUDIT)
    dump_csv(annotator_a_path, annotation_rows, SEGMENTS)
    dump_csv(annotator_b_path, annotation_rows, SEGMENTS)
    dump_csv(summary_path, summary_rows, ['group', 'value', 'count'])
    print(f'Đã chọn {len(pilot)} đoạn từ {pilot.document_id.nunique()} văn bản, seed={args.seed}.')
    print(f'File kiểm toán chọn mẫu: {master_path}')
    print(f'Hai biểu gán độc lập, không lộ tín hiệu heuristic: {annotator_a_path}, {annotator_b_path}')
    print('Mọi cột nhãn đều để trống; kết quả chọn mẫu không phải nhãn gold.')


def suggest_pilot_labels(args):
    """Sinh gợi ý máy cục bộ; tuyệt đối không phải nhãn gold hay người gán độc lập."""
    source = read_csv(args.input)
    require_columns(source, DRAFT, args.input)
    if source.segment_id.duplicated().any():
        raise SystemExit(f'{args.input}: segment_id bị trùng')
    output = project(args.output)
    no_overwrite(output, args.force)
    rows = []
    for record in source.to_dict('records'):
        text_normalized = normalized(record['segment_text'])
        task_terms = sorted(set(TASK_RX.findall(text_normalized)))
        commune_terms = sorted(set(COMMUNE_RX.findall(text_normalized)))
        suggested_task = int(bool(task_terms))
        suggested_commune = int(bool(suggested_task and commune_terms))
        text_length = len(stripped(record['segment_text']))
        task_confidence = 'medium' if len(task_terms) >= 2 else 'low'
        commune_confidence = 'medium' if suggested_commune and len(commune_terms) >= 1 else 'low'
        if text_length < 20:
            task_confidence = 'low'
            commune_confidence = 'low'
        rows.append(dict(
            document_id=record['document_id'],
            segment_id=record['segment_id'],
            source_location=record['source_location'],
            segment_text=record['segment_text'],
            suggested_task_present=suggested_task,
            suggested_commune_relevance=suggested_commune,
            task_confidence=task_confidence,
            commune_confidence=commune_confidence,
            matched_task_terms=';'.join(task_terms),
            matched_commune_terms=';'.join(commune_terms),
            suggestion_method='local_rule_keywords_v1',
            human_review_required='1',
            research_status='NON_GOLD_AI_SUGGESTION',
        ))
    dump_csv(output, rows, AI_SUGGESTIONS)
    counts = pd.DataFrame(rows)
    print(
        f'Đã tạo {len(rows)} gợi ý máy: '
        f'task=1: {int(counts.suggested_task_present.astype(int).sum())}, '
        f'commune=1: {int(counts.suggested_commune_relevance.astype(int).sum())}.'
    )
    print(f'File: {output}')
    print('CẢNH BÁO: NON_GOLD_AI_SUGGESTION; không dùng để tính Kappa/F1 hoặc thay nhãn con người.')


def predict_detection(args):
    splits = read_csv('data/splits/split_manifest.csv').set_index('document_id').split.to_dict()
    s = read_csv('data/annotations/segments_gold.csv')
    chosen = s[s.document_id.map(splits).eq(args.split)]
    if chosen.empty: raise SystemExit(f'Không có đoạn thuộc split={args.split}')
    rows = []
    for r in chosen.to_dict('records'):
        source = normalized(r['segment_text'])
        rows.append(dict(document_id=r['document_id'],segment_id=r['segment_id'],pred_task_present=int(bool(TASK_RX.search(source))),pred_commune_relevance=int(bool(COMMUNE_RX.search(source)))))
    p = project(f'results/predictions/detection_rules_{args.split}.csv')
    no_overwrite(p, args.force)
    dump_csv(p, rows, ['document_id','segment_id','pred_task_present','pred_commune_relevance'])
    print(f'Xuất {len(rows)} dự đoán (quy tắc CHỈ LÀ BASELINE): {p}')


def evaluate_detection(args):
    s = read_csv('data/annotations/segments_gold.csv')
    s = s[s.label_status.str.lower().eq('approved')]
    p = read_csv(f'results/predictions/detection_rules_{args.split}.csv')
    m = p.merge(s[['segment_id','task_present','commune_relevance','label_status']], on='segment_id', how='left', validate='one_to_one')
    if m.task_present.eq('').any(): raise SystemExit('Các dự đoán có đoạn chưa được duyệt nhãn; cần gán nhãn approved trước.')
    result = []
    for name, gold, pred, subset in [
        ('E1_phat_hien_nhiem_vu', 'task_present', 'pred_task_present', m),
        ('E2_loc_cap_xa_oracle_task', 'commune_relevance', 'pred_commune_relevance', m[m.task_present.eq('1')]),
    ]:
        if len(subset) == 0: continue
        pp, rr, ff, _ = precision_recall_fscore_support(subset[gold], subset[pred], labels=['1'], average='binary', pos_label='1', zero_division=0)
        result.append(dict(task=name, precision=pp, recall=rr, f1=ff, n=len(subset), split=args.split))
    out = project(f'results/metrics/detection_{args.split}.csv')
    no_overwrite(out, args.force)
    dump_csv(out, result, ['task','precision','recall','f1','n','split'])
    print(pd.DataFrame(result).to_string(index=False))
    print('Lưu ý: E2 đo trên các đoạn gold có nhiệm vụ; KHÔNG phải E2 end-to-end.')



def qc_labels(args):
    """Compare independent segment-level labels; task span adjudication is separate."""
    a=read_csv(args.annotator_a)
    b=read_csv(args.annotator_b)
    needed=['segment_id','task_present','commune_relevance','annotator_id']
    for name,df in [('A',a),('B',b)]:
        for c in needed:
            if c not in df: raise SystemExit(f'File {name} thiếu {c}')
        if df.segment_id.duplicated().any(): raise SystemExit(f'File {name}: segment_id bị trùng')
    m=a[needed].merge(b[needed],on='segment_id',suffixes=('_a','_b'),how='outer',indicator=True,validate='one_to_one')
    if (m['_merge']!='both').any(): raise SystemExit('Hai người phải gán độc lập trên cùng một danh sách segment_id; cần xử lý trường hợp thiếu/trùng')
    res=[]; conflicts=[]
    for c in ['task_present','commune_relevance']:
        aa=m[c+'_a']; bb=m[c+'_b']
        if (~aa.isin(['0','1'])).any() or (~bb.isin(['0','1'])).any(): raise SystemExit(f'Nhóm {c} có nhãn chưa điền hoặc không hợp lệ')
        k=cohen_kappa_score(aa,bb,labels=['0','1'])
        agree=float((aa==bb).mean())
        res.append(dict(field=c,n=len(m),raw_agreement=agree,cohen_kappa=k))
        for rec in m[aa!=bb].to_dict('records'):
            conflicts.append(dict(segment_id=rec['segment_id'],field=c,label_a=rec[c+'_a'],label_b=rec[c+'_b'],resolution='',adjudicator='',reason=''))
    out=project('results/metrics/annotation_qc.csv')
    no_overwrite(out,args.force)
    dump_csv(out,res,['field','n','raw_agreement','cohen_kappa'])
    dump_csv(project('results/errors/annotation_conflicts.csv'),conflicts,['segment_id','field','label_a','label_b','resolution','adjudicator','reason'])
    print(pd.DataFrame(res).to_string(index=False))
    print(f'Có {len(conflicts)} bất đồng nhãn cần trọng tài xác nhận; Kappa không thay thế kiểm tra nhãn ở mức task/span.')


def unit_candidates(config, date_str):
    candidates = []
    for u in config['units']:
        if not u.get('unit_id') or not u.get('description') or not u.get('authority_source'):
            raise SystemExit('config/units.json phải có unit_id, description, authority_source cho mỗi phòng')
        if date_str:
            if u.get('valid_from') and date_str < str(u['valid_from']): continue
            if u.get('valid_to') and date_str > str(u['valid_to']): continue
        candidates.append(u)
    return candidates


def lexical_score(task, unit):
    x = normalized(task)
    words = [normalized(k).strip() for k in unit.get('keywords', []) if normalized(k).strip()]
    return sum(k in x for k in words) / max(1, len(words))


def predict_routing(args):
    cfgpath = project(args.units)
    config = json.loads(cfgpath.read_text(encoding='utf-8'))
    if config.get('policy_version') == 'CHUA_XAC_NHAN' or not config.get('units'):
        raise SystemExit('Phải điền config/units.json bằng các phòng và căn cứ THẬT trước khi chạy.')
    splits = read_csv('data/splits/split_manifest.csv').set_index('document_id').split.to_dict()
    t = read_csv('data/annotations/tasks_gold.csv')
    t = t[(t.document_id.map(splits) == args.split) & (t.commune_relevance == '1') & (t.label_status.str.lower() == 'approved')]
    if t.empty: raise SystemExit('Không có nhiệm vụ approved thuộc cấp xã trong split này.')
    embed_model = None
    if args.method in ('embedding','hybrid'):
        try:
            from sentence_transformers import SentenceTransformer
        except ImportError:
            raise SystemExit('Cần pip install -r requirements-ml.txt cho embedding/hybrid')
        embed_model = SentenceTransformer(args.model, device='cpu')
        import numpy as np
        all_units = config['units']
        unit_vectors = embed_model.encode([u['description'] for u in all_units], normalize_embeddings=True)
        vectors = {u['unit_id']: v for u, v in zip(all_units, unit_vectors)}
        task_vectors = embed_model.encode(t.task_text.tolist(), normalize_embeddings=True)
    else:
        task_vectors = [None]*len(t)
    out = []
    for (_, r), tv in zip(t.iterrows(), task_vectors):
        units = unit_candidates(config, r['routing_as_of'])
        scores = []
        for u in units:
            if any(normalized(pat) in normalized(r['task_text']) for pat in u.get('deny_keywords', [])):
                continue  # human-specified exclusions MUST have a source
            kw = lexical_score(r['task_text'], u)
            if args.method == 'rule': val = kw
            else:
                import numpy as np
                cos = float(np.dot(tv, vectors[u['unit_id']]))
                semantic = max(0., min(1., (cos + 1) / 2))
                val = semantic if args.method == 'embedding' else args.alpha*semantic + (1-args.alpha)*kw
            scores.append((u['unit_id'], val))
        scores.sort(key=lambda x: x[1], reverse=True)
        a = scores[0] if scores else ('', 0.)
        b = scores[1] if len(scores)>1 else ('', 0.)
        # If margin is low, system abstains on top1; top2 are candidates ONLY.
        abstain = not a[0] or a[1] < args.threshold or (b[0] and a[1]-b[1] < args.margin)
        out.append(dict(task_id=r['task_id'],document_id=r['document_id'],method=args.method,top1=('<ABSTAIN>' if abstain else a[0]),candidate1=a[0],candidate2=b[0],score1=round(a[1],6),score2=round(b[1],6),abstain=int(abstain),model=(args.model if embed_model else ''),alpha=args.alpha,threshold=args.threshold,margin=args.margin))
    path = project(f'results/predictions/routing_{args.method}_{args.split}.csv')
    no_overwrite(path, args.force)
    dump_csv(path,out,list(out[0].keys()))
    print(f'Đã lưu {len(out)} dự đoán: {path}')
    print('Các ngưỡng alpha, threshold, margin chỉ được chọn bằng tập DEV, khóa trước TEST.')


def evaluate_routing(args):
    t = read_csv('data/annotations/tasks_gold.csv')
    p = read_csv(f'results/predictions/routing_{args.method}_{args.split}.csv')
    t = t[(t.label_status.str.lower() == 'approved') & (t.commune_relevance == '1')]
    merged = p.merge(t[['task_id','gold_unit','label_status']], on='task_id',how='left',validate='one_to_one')
    if merged.gold_unit.eq('').any(): raise SystemExit('Có dự đoán không có gold_unit được xác nhận.')
    y=merged.gold_unit.tolist(); pred=merged.top1.tolist()
    labels=sorted(set(y))
    correct=[int(a==b) for a,b in zip(y,pred)]
    top2=[int(y0 in {p1,p2}) for y0,p1,p2 in zip(y,merged.candidate1,merged.candidate2)]
    coverage=sum(z != '<ABSTAIN>' for z in pred)/len(pred)
    results=[dict(task='E4_phan_luong',method=args.method,split=args.split,n=len(y),top1_accuracy=sum(correct)/len(correct),top2_accuracy=sum(top2)/len(top2),macro_f1=f1_score(y,pred,labels=labels,average='macro',zero_division=0),coverage=coverage)]
    out=project(f'results/metrics/routing_{args.method}_{args.split}.csv')
    no_overwrite(out,args.force)
    dump_csv(out,results,list(results[0].keys()))
    errors=merged[merged.gold_unit != merged.top1]
    dump_csv(project(f'results/errors/routing_{args.method}_{args.split}.csv'),errors.to_dict('records'),list(merged.columns))
    print(pd.DataFrame(results).to_string(index=False))
    print(f'Sai/abstain: {len(errors)}/{len(merged)}; file phân tích lỗi đã ghi.')


def evaluate_extraction(args):
    """Oracle task alignment, NOT E5. Each predicted task_id must refer to pre-existing gold task_id."""
    gold=read_csv('data/annotations/tasks_gold.csv')
    gold=gold[gold.label_status.str.lower().eq('approved')]
    p=read_csv('data/annotations/extraction_predictions.csv')
    splits=read_csv('data/splits/split_manifest.csv').set_index('document_id').split.to_dict()
    gold=gold[gold.document_id.map(splits).eq(args.split)]
    if gold.empty or p.empty: raise SystemExit('Cần gold approved và extraction_predictions đã chạy thực tế.')
    joined=gold.merge(p[['task_id','task_text','source_actor','deadline_iso','deliverable']],on='task_id',how='left',suffixes=('_gold','_pred'),validate='one_to_one')
    fields=['task_text','source_actor','deadline_iso','deliverable']
    rows=[]
    for f in fields:
        ok=[stripped(str(x))==stripped(str(y)) for x,y in zip(joined[f+'_gold'],joined[f+'_pred'].fillna(''))]
        rows.append(dict(field=f,exact_match=sum(ok)/len(ok),n=len(ok),split=args.split))
    complete=[]
    for _,r in joined.iterrows():
        complete.append(all(stripped(str(r[f+'_gold']))==stripped(str(r[f+'_pred'])) for f in fields))
    rows.append(dict(field='record_exact_match_ORACLE_ALIGNMENT',exact_match=sum(complete)/len(complete),n=len(complete),split=args.split))
    out=project(f'results/metrics/extraction_oracle_{args.split}.csv')
    no_overwrite(out,args.force)
    dump_csv(out, rows, list(rows[0].keys()))
    print(pd.DataFrame(rows).to_string(index=False))
    print('CẢNH BÁO: Các task_id ở đây được khớp bằng gold (oracle). Không thể gọi đây là E5 hoặc end-to-end.')


def evaluate_e5(args):
    gold=read_csv('data/annotations/tasks_gold.csv')
    splits=read_csv('data/splits/split_manifest.csv').set_index('document_id').split.to_dict()
    gold=gold[(gold.label_status.str.lower().eq('approved')) & (gold.document_id.map(splits).eq(args.split))]
    m=read_csv('data/annotations/e5_matches.csv')
    if gold.empty or m.empty: raise SystemExit('Cần gold tasks approved và bảng E5 gán cặp độc lập từ kết quả hệ thống thực tế.')
    if m.gold_task_id.duplicated().any(): raise SystemExit('E5 mỗi gold_task_id xuất hiện đúng một lần; một gold không được ghép nhiều prediction.')
    if set(m.gold_task_id) != set(gold.task_id): raise SystemExit('E5 phải bao phủ 100% gold task_id của split; ghi pred_task_id trống khi mô hình bỏ sót.')
    for field in ['task_correct','actor_correct','deadline_correct','unit_correct']:
        if not m[field].isin(['0','1']).all(): raise SystemExit(f'{field} phải là 0 hoặc 1 đã được người kiểm chứng.')
    task_em=(m.task_correct.eq('1') & m.actor_correct.eq('1') & m.deadline_correct.eq('1'))
    final_em=task_em & m.unit_correct.eq('1')
    row=dict(task='E5_golddenominator',split=args.split,n_gold=len(m),record_exact_match=float(task_em.mean()),end_to_end_with_correct_unit=float(final_em.mean()),note='Chưa tính false positive; đo recall-like dựa trên tất cả gold tasks')
    out=project(f'results/metrics/e5_{args.split}.csv')
    no_overwrite(out,args.force)
    dump_csv(out,[row],list(row.keys()))
    print(pd.DataFrame([row]).to_string(index=False))
    print('BẮT BUỘC báo cáo riêng số dự đoán thừa (FP) và cách ghép prediction/gold. Đây CHƯA LÀ precision/F1 end-to-end.')


def audit(args):
    import importlib.metadata as md
    names=['pandas','scikit-learn','numpy','PyMuPDF','python-docx','transformers','sentence-transformers','torch']
    versions={}
    for x in names:
        try: versions[x]=md.version(x)
        except md.PackageNotFoundError: versions[x]='not installed'
    manifest=project('data/processed/documents_manifest.csv')
    raw=[]
    if manifest.exists():
        m=read_csv(manifest)
        for r in m.to_dict('records'):
            p=project(r['filename'])
            raw.append(dict(document_id=r['document_id'], filename=r['filename'], sha256_current=(sha256(p) if p.exists() else 'MISSING'), sha256_recorded=r['file_sha256']))
    d=dict(utc=datetime.now(timezone.utc).isoformat(),python=sys.version,os=platform.platform(),packages=versions,files=raw,argv=sys.argv,comment='Bằng chứng môi trường; không phải kết quả thực nghiệm.')
    out=project(f'evidence/audit_{datetime.now(timezone.utc).strftime("%Y%m%d_%H%M%S")}.json')
    out.write_text(json.dumps(d,ensure_ascii=False,indent=2),encoding='utf-8')
    print(f'Đã lưu kiểm kê môi trường và hash: {out}')


